# Common functions for orchestrating state and side effects
def get_status():
    """Get current charm status message."""
    return unitdata.kv().get('jenkins.status')

def set_status(message):
    """Set charm status message in local state."""
    unitdata.kv().set('jenkins.status', message)

def require_relation_state(relation_name):
    """Check if a specific relation is established."""
    return get_state(f"{relation_name}.connected")

def data_changed_with_key(key, data):
    """Wrapper for data_changed that handles None values safely."""
    if data is None:
        return False
    return data_changed(key, data)

def safe_call(func):
    """Decorator to handle exceptions and log appropriately."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            hookenv.log(f"Error in {func.__name__}: {str(e)}", level='ERROR')
            raise
    return wrapper

def warn_plugin_issue(plugins, incompatible_plugins):
    """Log and set status for plugin installation issues."""
    if incompatible_plugins:
        hookenv.log(
            "The following plugins require a higher jenkins version and were not installed: (%s)" % 
            " ".join(incompatible_plugins)
        )
        hookenv.status_set(
            "blocked",
            "There were plugins not compatible with this jenkins version. Consider upgrading jenkins or removing the plugins."
        )
